                            {isChecked && (
                              <div className="mt-3 bg-white p-2.5 rounded-xl border border-slate-200/60 shadow-xs">
                                {renderMultiSelect(pillarKey, icon, `Choose ${labelMap[pillarKey]} Options`, optionsMap[pillarKey])}
