                    <div className="flex flex-col items-center justify-center gap-2">
                      <Folder className="h-8 w-8 text-slate-300" />
                      <div className="font-medium text-slate-600">No campaigns found</div>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </motion.div>
  );
}

