  return (
    <div className="mx-auto max-w-7xl pb-20">
      <div className="mb-6">
        <button 
          onClick={onBack}
          className="mb-4 inline-flex items-center gap-2 text-sm font-medium text-slate-500 hover:text-[#6D5DF6] transition-colors"
